#include <bits/stdc++.h>
using namespace std;

// Using Kosa Raju, we guarantee the topmost element (indicated by root) of stack is from the root SCC

void DFS(int v, bool visited[], int &root, vector<int> edges[])
{
    visited[v] = true;
    for (auto it : edges[v])
        if (!visited[it])
            DFS(it, visited, root, edges);
    root = v;
}

int cnt(int v, bool visited[], vector<int> edges[])
{
    int ans = 1;
    visited[v] = true;
    for (auto it : edges[v])
        if (!visited[it])
            ans += cnt(it, visited, edges);
    return ans;
}

int main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);
    int T;
    cin >> T;
    while (T--)
    {
        int i, j, n, m, u, v, w;
        cin >> n >> m;
        vector<pair<int, int>> og_edges[n];
        for (i = 0; i < m; i++)
        {
            cin >> u >> v >> w;
            u--, v--;

            og_edges[u].push_back({v, w});
        }

        int l = -1, r = 1e9 + 1, mid;
        while (r - l > 1)
        {
            mid = l + (r - l) / 2;

            vector<int> edges[n];
            for (i = 0; i < n; i++)
            {
                for (auto it : og_edges[i])
                {
                    edges[i].push_back(it.first);
                    if (it.second <= mid)
                        edges[it.first].push_back(i);
                }
            }

            bool visited[n] = {};
            int root;
            for (i = 0; i < n; i++)
            {
                if (!visited[i])
                    DFS(i, visited, root, edges);
            }

            memset(visited, false, sizeof(visited));

            if (cnt(root, visited, edges) == n)
                r = mid;
            else
                l = mid;
        }

        if (r == 1e9 + 1)
            r = -1;
        cout << r << '\n';
    }
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

struct Trie{
	struct Trie *child[2]={0};
};
typedef struct Trie trie;

void insert(trie *dic, int x)
{
	trie *temp = dic;
	for(int i=30;i>=0;i--) 
	{
		int curr = x>>i&1;
		if(temp->child[curr])
			temp = temp->child[curr];
		else
		{
			temp->child[curr] = new trie;
			temp = temp->child[curr];
		}
	}
}

int find_greatest(trie *dic, int x) {
	int res = 0;
	trie *temp = dic;
	for(int i=30;i>=0;i--) {
		int curr = x>>i&1;
		if(temp->child[curr^1]) {
			res ^= 1<<i;
			temp = temp->child[curr^1];
		}
		else {
			temp = temp->child[curr];
		}
	}
	return res;	
}

int main() {
	int test_cases;
	cin >> test_cases;
	while(test_cases--)
	{
		int n;
		cin>>n;
		int a[n+1];
		for(int i=1;i<=n;i++) {
			cin>>a[i];
		}

		trie *t[n+2];
		int prexor[n+1];
		prexor[0] = 0;
		for(int i=1;i<=n;i++) {
			t[i] = new trie;
			insert(t[i], prexor[i-1]);
			prexor[i] = prexor[i-1]^a[i];
		}
		t[n+1] = new trie;
		insert(t[n+1], prexor[n]);

		pair<int,int> asc[n+1];
		for(int i=1;i<=n;i++) {
			asc[i] = make_pair(a[i],i);
		}
		sort(asc+1,asc+n+1);

		int left[n+1], right[n+1];
		stack<int> s;
		for(int i=1;i<=n;i++) {
			while(!s.empty() && a[i]>=a[s.top()])
				s.pop();
			if(s.empty())
				left[i] = 0;
			else
				left[i] = s.top();
			s.push(i);
		}
		while(!s.empty()) 
			s.pop();
		for(int i=n;i>0;i--) {
			while(!s.empty() && a[i]>a[s.top()])
				s.pop();
			if(s.empty())
				right[i] = n+1;
			else
				right[i] = s.top();
			s.push(i);
		}

		int ans = 0;
		for(int i=1;i<=n;i++) {
			int x = asc[i].second;
			int r = right[x]-1;
			int l = left[x]+1;
			if(x-l < r-x) {
				for(int j=l-1;j<x;j++) {
					ans = max(ans, find_greatest(t[x+1], prexor[j]^a[x]));
				}
				t[l] = t[x+1];
				for(int j=l-1;j<x;j++) {
					insert(t[l], prexor[j]);
				}
			}
			else {
				for(int j=x;j<=r;j++) {
					ans = max(ans, find_greatest(t[l], prexor[j]^a[x]));
				}
				for(int j=x;j<=r;j++) {
					insert(t[l], prexor[j]);
				}
			}
		}
		cout<<ans << endl;
	}
}
